[1879056755]={[1]="Silfdraum";[2]="This helm was named not for its colour, but for the dream the wearer had of returning to Khazad-dûm and recovering the Moria-silver found there.";[3]=7;[4]=2;[5]=3;[6]=false;[7]=false;};
