[1879155830]={[1]="Nimble Hill-goat";[2]="As a great ally of the Iron Garrison Miners, one can expect access to their most well-trained and quickest goats. The hill-goats are somewhat smaller than Redhorn-goats making them perfect mounts for hobbits and dwarves. This goat can move as fast as most horses.";[3]=8;[4]=5;[5]=0;[6]=false;[7]=true;};
[1879155833]={[1]="Tame Hill-goat";[2]="The Iron Garrison Miners have been training hill-goats to use as mounts. These sure-footed creatures can traverse the rocky passageways of Moria where no horse could go. The hill-goats are somewhat smaller than Redhorn-goats making them perfect mounts for hobbits and dwarves. This is one of their tame goats, making it not as fast as others.";[3]=8;[4]=5;[5]=0;[6]=false;[7]=true;};
[1879155867]={[1]="Deserter's Note";[2]="This note was written by a goblin-deserter to one of his companions. It is written in Black Speech and is incomprehensible to you.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156286]={[1]="Luminous Stinger";[2]="A bright stinger from a Drownholt firefly, filled with a deadly luminous venom.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156378]={[1]="Orc Leader's Coffer";[2]="This coffer belongs to a leader of Orcs and contains his plans and other valuables.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156409]={[1]="Laidhris Dose";[2]="The Laidhris has been prepared with care, but will it work?";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156410]={[1]="Sereglos Flower";[2]="This flower grew once upon a lonely barrow beneath the dark canopy of Mirkwood.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
