[1879156694]={[1]="Silvan Relic";[2]="Ancient Elvish relics of a bygone age in Mirkwood. Many seem to have been scarred or defaced in some manner.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156695]={[1]="Glowing Gland";[2]="A strangely glowing gland from a firefly in Emyn Lûm. Its odd light cuts through the everpresent mists.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156696]={[1]="Obsidian Gem";[2]="A cold gem of some strange black substance -- it feels like obsidian, but it absorbs all light that falls upon it.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156697]={[1]="Vital Missive";[2]="A sealed scroll containing critical information about the Malledhrim forward advance against Dol Guldur.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156699]={[1]="Anti-venom";[2]="A phial of anti-venom to counteract the deadly black poison of Delúris Just a few drops should do the trick, but the taste is indescribably awful.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156700]={[1]="Gnawed Bones";[2]="A pile of bones that belonged to some sort of small humanoid - well chewed by the barghests of the Scuttledells.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156701]={[1]="Torn Pack";[2]="A small hobbit pack, torn in places and spattered with flecks of blood.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156703]={[1]="Barrow Seal";[2]="This runic seal has been recently carved, and a faint silvery sheen can be seen upon the runes when it is held up under bright starlight.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156704]={[1]="Black Poison Gland";[2]="The poison gland of one of Delúris' black brood that infest the Scuttledells of Mirkwood.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156705]={[1]="War Collar";[2]="A cruelly studded collar of coarse, heavy leather. They are worn by the Wargs that prowl the region of Taur Morvith.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156709]={[1]="Ancient Silvan Record";[2]="Records of the ancient Silvan community that once thrived here in the forests east of the Anduin.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156710]={[1]="Corrupted Silvan Relic";[2]="An old relic of the Elves -- but like so much else here in Mirkwood it has been tainted and corrupted by the arts of the Enemy. Better that it be destroyed than left in their hands.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156711]={[1]="Odd Footprints";[2]="Unusual footprints can be seen here in the mud. They look a bit like hobbit feet, but oddly distorted and elongated for one of their kind.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879156713]={[1]="Dreadful Pyre";[2]="The flames that dance about this pyre burn with a dreadful, unnatural hue, and the smoke that claws its way up into the sky creates a hideous pall over the surrounding lands.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
