[1879217335]={[1]="Superior Quick Trap";[2]="A superior quick trap, capable of being set almost instantly in the midst of a fight. The trap remains for 60 seconds after being placed. Most effective against targets level 75 or lower. Mounted Combat Enemies: Root replaced with a mount acceleration debuff";[3]=20;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879217336]={[1]="Westfold Caltrops";[2]="Westfold caltrops damage the target while decreasing its run speed. Most effective against targets level 80 or lower.";[3]=48;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879217337]={[1]="Westfold Triple-trap";[2]="A Westfold triple-trap, capable of trapping up to three targets. The traps remain for 60 seconds after being placed. Most effective against targets level 80 or lower. Mounted Combat Enemies: Root replaced with a mount acceleration debuff";[3]=20;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879217338]={[1]="Westfold Quick Trap";[2]="A Westfold quick trap, capable of being set almost instantly in the midst of a fight. The trap remains for 60 seconds after being placed. Most effective against targets level 80 or lower. Mounted Combat Enemies: Root replaced with a mount acceleration debuff";[3]=20;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879217339]={[1]="Superior Tripwire";[2]="A superior tripwire which can knock a monster over, sometimes creating the opportunity to use Fellowship Manoeuvres. The trap must be placed before combat and remains for 60 seconds after being placed. Most effective against targets level 75 or lower. Mounted Combat Enemies: Knockout and Knockdown replaced with a mount turn rate debuff";[3]=20;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879217340]={[1]="Superior Strong Trap";[2]="A superior strong trap does not hold as long, but will not release the target when damaged. The trap remains for 60 seconds after being placed. Most effective against targets level 75 or lower. Mounted Combat Enemies: Root replaced with a mount acceleration debuff";[3]=20;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879217341]={[1]="Superior Bear-trap";[2]="A superior bear-trap, capable of trapping and damaging a target. The trap remains for 3 minutes after being placed. Most effective against targets level 75 or lower. Mounted Combat Enemies: Root replaced with a mount acceleration debuff";[3]=20;[4]=5;[5]=0;[6]=false;[7]=false;};
