[1879342301]={[1]="Dagorlad Weapon Scrap";[2]="The scrap of battles past. It cannot be used to make new equipment, but it will work just fine to reinforce equipment damaged at the Pelennor.";[3]=37;[4]=2;[5]=0;[6]=false;[7]=false;};
[1879342302]={[1]="Bolt of Rush-cloth";[2]="Made from coarse rush fibres taken from the Dead Marshes. Not very comfortable, but surprisingly sturdy.";[3]=37;[4]=2;[5]=0;[6]=false;[7]=false;};
