[1879342305]={[1]="Cap of Evengleam";[2]="Not to everyone's taste, but someone, somewhere, will regard it as a delicacy.";[3]=37;[4]=2;[5]=0;[6]=false;[7]=false;};
[1879342306]={[1]="Bundle of Reclaimed Ithilien Lumber";[2]="Wood stolen from North Ithilien, now reclaimed for use by the Free Peoples.";[3]=37;[4]=2;[5]=0;[6]=false;[7]=false;};
