[1879342309]={[1]="Rangers' Journal of Dagorlad Cookery";[2]="The Rangers of Ithilien have experience with foraging and cooking in Dagorlad.";[3]=37;[4]=2;[5]=0;[6]=false;[7]=false;};
[1879342310]={[1]="Rangers' Journal of Dagorlad Woodworking";[2]="Masters of the local woodlands, the Rangers of Ithilien are skilled woodworkers.";[3]=37;[4]=2;[5]=0;[6]=false;[7]=false;};
[1879342311]={[1]="Rangers' Journal of Dagorlad Weaponsmithing";[2]="The Rangers of Ithilien are skilled at repairing equipment with whatever is at hand.";[3]=37;[4]=2;[5]=0;[6]=false;[7]=false;};
