[1879348829]={[1]="Log of Gorgoroth Wood";[2]="Harsh, knotty wood just stubborn enough to survive in Gorgoroth. This can be turned into treated wood by a Doomfold Forester.";[3]=56;[4]=4;[5]=0;[6]=false;[7]=false;};
