[1879348831]={[1]="Chunk of High-grade Doomfold Skarn";[2]="This rare piece of skarn contains an abundance of Doomfold ore, which can be smelted by experienced Doomfold Prospectors. High-quality skarn contains pure Gorgoroth ore, which can be extracted and used in some Doomfold Jeweller, Metalsmith, Prospector, and Weaponsmith recipes to increase the chance of critical success.";[3]=56;[4]=2;[5]=0;[6]=false;[7]=false;};
[1879348832]={[1]="Tattered Doomfold Parchment";[2]="The ancient words on this parchment, written in vile tongue, are faded and timeworn. This item can be used by Doomfold Scholars.";[3]=56;[4]=4;[5]=0;[6]=false;[7]=false;};
[1879348833]={[1]="Strong Gorgoroth Branch";[2]="This rare type of Gorgoroth wood can be used by experienced Doomfold Foresters to make Doomfold bark, which is used in some Doomfold Forester, Tailor, and Woodworker recipes to increase the chance of critical success.";[3]=56;[4]=2;[5]=0;[6]=false;[7]=false;};
[1879348834]={[1]="Piece of Doomfold Sealed Wax";[2]="This rare piece of sealed wax can be turned into a candle by experienced Doomfold Scholars and used in some Doomfold Scholar recipes to increase the chance of critical success.";[3]=56;[4]=2;[5]=0;[6]=false;[7]=false;};
[1879348835]={[1]="Doomfold Hide";[2]="The harshness of Gorgoroth has made this hide thick and strong. This can be turned into leather by a Doomfold Forester.";[3]=56;[4]=4;[5]=0;[6]=false;[7]=false;};
[1879348836]={[1]="Black Adamant";[2]="An uncut gemstone. Aside from being black as pitch, it possesses similar properties to Adamant. This can be polished by a Doomfold Jeweller.";[3]=56;[4]=4;[5]=0;[6]=false;[7]=false;};
