[1879366413]={[1]="Troll Sweat";[2]="This thin ale isn't really made from the sweat of trolls, but it is still best to stay in Ránnvig's good graces or she might make an exception.";[3]=55;[4]=2;[5]=0;[6]=false;[7]=false;};
