[1879383084]={[1]="Reinforced Winterstith Leggings of Fortitude";[2]="‘Let the Óinsbridge be a reminder to us that our actions will remain, even once we are gone! These dragons cannot best us!’ - King Óin’s son Dáin, shortly before he disappeared in the Ered Mithrin";[3]=15;[4]=3;[5]=3;[6]=false;[7]=false;};
