[1879395459]={[1]="Morgul Explorer's Brass Stud";[2]="";[3]=49;[4]=4;[5]=3;[6]=false;[7]=false;};
[1879395460]={[1]="Morgul Explorer's Jade Silver Earring";[2]="";[3]=49;[4]=4;[5]=3;[6]=false;[7]=false;};
[1879395461]={[1]="Morgul Explorer's Carved Jade Ring";[2]="";[3]=49;[4]=4;[5]=3;[6]=false;[7]=false;};
