[1879404061]={[1]="Packed Belongings";[2]="Imák carried his belongings from Skarháld and did not complain about the weight of them until he set them down.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879404062]={[1]="Statue of Durin";[2]="Stáli the Hewer takes a great deal of pride in sculptures of his creation, but none more than this statue of Durin the Deathless, who awoke during the First Age of Middle-earth.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
