[1879404064]={[1]="Drink in Silence";[2]="The water is warm and will win no awards for taste, but it will serve its purpose: allowing the conversation to ebb while you slake your thirst.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
