[1879448389]={[1]="Herne Town Brazier";[2]="A number of braziers have been found within several of the town's buildings and dragged outside. It is to be hoped their burning fires will keep the darkness from encroaching again upon the town.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
