[1879448391]={[1]="Assortment of Scattered Papers";[2]="You have retrieved parchments containing the grand designs of many different interests in Cardolan, and must now sort through them if you are to make sense of their intricate web.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879448392]={[1]="Wreckage and Debris";[2]="The Hall of the Swift River was damaged by both war and the passage of the years; today only debris remains.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
