[1879487766]={[1]="Camp-fire Site";[2]="This once served as a campsite for residents of Urash Dâr. Now abandoned, it will serve your travelling company instead.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487767]={[1]="Fallen Wall-stone";[2]="This stone fell from Telperiën's Wall sometime during its long history, joining others of its kind on the ground. When there were enough fallen stones lying in the grass the masons abandoned efforts to replace them.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487768]={[1]="Scorpion Stinger";[2]="The people of Urmâkh have asked you to return with stingers from the scorpions that crawl throughout Imhûlar.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487769]={[1]="Zizanu Bristles";[2]="Insect parts of all kinds can be used by the folk of Urmâkh, but whether those needs are worth the effort remains unknown to you.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487770]={[1]="Jackal Teeth";[2]="You believed the jackals of Khûd Zagin were the largest and most ferocious you had ever seen, but the jackals of Urash Dâr put even those creatures to shame.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487771]={[1]="Diseased Deer-hide";[2]="The creatures who live still in Imhûlar have been stricken with a debilitating disease for which no cure has yet been found.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487772]={[1]="Satchel Contents";[2]="The satchel contained enough supplies for a journey of many days. Why would someone leave it behind?";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487773]={[1]="Diseased Serval-fang";[2]="The creatures who live still in Imhûlar have been stricken with a debilitating disease for which no cure has yet been found.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487774]={[1]="Boundary Stones";[2]="The Kintai performed a ritual upon these stones, and they believe their presence will protect Vartúlin from enemy incursions.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487775]={[1]="Jar of Water";[2]="This small jar contains clean water.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487776]={[1]="Diseased Boar-hoof";[2]="The creatures who live still in Imhûlar have been stricken with a debilitating disease for which no cure has yet been found.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487777]={[1]="Khôltekh's Parchment";[2]="Khôltekh gave you this parchment so you can sketch him a map to the vaults of Ashâgir.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487778]={[1]="Order For Weapons";[2]="Rothog gave you these orders to deliver to the arena's famed armourer so he will know what equipment to provide for the journey.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487779]={[1]="Token of the Eye";[2]="This small bronze token is marked with the crude representation of an unblinking eye. It is the symbol of the Church of the All-seeing, and that of Sauron.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487780]={[1]="Water Bladder";[2]="No traveller should be without a container such as this when journeying in the arid climate of the south.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487781]={[1]="Bird Feathers";[2]="The birds of Khûd Zagin are similar to others you have seen, if perhaps hardier and more aggressive.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487782]={[1]="Kanash-tubu-hârra";[2]="Written by an unknown author, this treatise on his rarely-seen and difficult to master combat style is prized by the warriors who fight on the sands of Dahâl Huliz.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487783]={[1]="Healing Poultice";[2]="Babarín prepared this healing poultice to ease the hurts of the injured man recovering in Ghalbûru.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487784]={[1]="Hardy Plant Leaves";[2]="The edges of these hardy leaves are sharp and might cut you if handled improperly, so you take special care.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487785]={[1]="Craban Claw";[2]="The crebain of Urash Dâr possess terrible and frightening hooked claws of a type you have never seen before. Combined with their savage beaks, these claws can tear through flesh most rapidly.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487786]={[1]="Order For Supplies";[2]="Khôltekh gave you these orders to deliver to the warehouse keeper so she may arrange for the supplies the company will need for the journey.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487787]={[1]="Toad Legs";[2]="The people of Urmâkh want toad legs, but whether they are intended to be used by a cook or a healer is unknown.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487788]={[1]="Pigment Berries";[2]="Young scholars newly in the service of Umbar are charged with picking the berries used to make the pigments and inks needed in the archives.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487789]={[1]="Sand-sifter Meat";[2]="This meat is lean and tough, but the Kintai must know how to prepare it in such a way that those qualities can be sufficiently overcome.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487790]={[1]="Order For A Caravan";[2]="Hármelak gave you these orders to deliver to the caravan master charged with arranging the departure of the company.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
[1879487791]={[1]="Sharp Jackal Tooth";[2]="The jackals of Khûd Zagin possess teeth sharper than you have seen in other similar creatures elsewhere, but you cannot determine why that might be.";[3]=27;[4]=5;[5]=0;[6]=false;[7]=false;};
